using Dm;

var connectionString = Environment.GetEnvironmentVariable("DM8_CONNECTION_STRING");
if (string.IsNullOrWhiteSpace(connectionString))
    throw new InvalidOperationException("DM8_CONNECTION_STRING is required.");
if (args.Length != 1)
    throw new ArgumentException("Pass exactly one SQL migration file.");

var statements = (await File.ReadAllTextAsync(args[0]))
    .Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

await using var connection = new DmConnection(connectionString);
await connection.OpenAsync();

await using (var check = connection.CreateCommand())
{
    check.CommandText = "SELECT COUNT(*) FROM FLOW_RELIABILITY.WORKFLOW_SCHEMA_VERSION WHERE VERSION_NO = 5";
    if (Convert.ToInt32(await check.ExecuteScalarAsync()) > 0)
    {
        Console.WriteLine("MIGRATION_5_ALREADY_APPLIED");
        return;
    }
}

await using var transaction = await connection.BeginTransactionAsync();
try
{
    foreach (var statement in statements)
    {
        await using var command = connection.CreateCommand();
        command.Transaction = transaction;
        command.CommandText = statement;
        await command.ExecuteNonQueryAsync();
    }
    await transaction.CommitAsync();
    Console.WriteLine("MIGRATION_5_APPLIED");
}
catch
{
    await transaction.RollbackAsync();
    throw;
}

