using System.Collections.Generic;
using System.Threading.Tasks;
using FlowableWrapper.Application.Dtos;
using FlowableWrapper.Application.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;

namespace FlowableWrapper.HttpApi.Controllers
{
    [Route("api/flowable/bpmn")]
    public class BpmnController : ControllerBase
    {
        private readonly BpmnDeploymentAppService _bpmnService;

        public BpmnController(BpmnDeploymentAppService bpmnService)
        {
            _bpmnService = bpmnService;
        }

        /// <summary>
        /// 部署 BPMN 文件
        /// POST /api/flowable/bpmn/deploy
        ///
        /// Content-Type: multipart/form-data
        ///   file          : .bpmn 文件
        ///   slotConfigJson: 节点配置 JSON 字符串（见 slotConfig_v2.json）
        /// </summary>
        [HttpPost("deploy")]
        [Consumes("multipart/form-data")]
        public async Task<BpmnDeploymentResponse> Deploy(
            [FromForm] IFormFile file,
            [FromForm] string slotConfigJson)
        {
            return await _bpmnService.DeployAsync(file, slotConfigJson);
        }

        /// <summary>
        /// 查询流程定义节点语义（含驳回选项和 Slot 定义）
        /// GET /api/flowable/bpmn/{processDefinitionKey}/nodes
        /// </summary>
        [HttpGet("{processDefinitionKey}/nodes")]
        public async Task<List<ProcessDefinitionNodeDto>> GetNodes(
            string processDefinitionKey)
        {
            return await _bpmnService.GetProcessDefinitionNodesAsync(processDefinitionKey);
        }

        /// <summary>
        /// 删除部署
        /// DELETE /api/flowable/bpmn/deployments/{deploymentId}?cascade=true
        /// </summary>
        [HttpDelete("deployments/{deploymentId}")]
        public async Task<IActionResult> DeleteDeployment(
            string deploymentId,
            [FromQuery] bool cascade = true)
        {
            await _bpmnService.DeleteDeploymentAsync(deploymentId, cascade);
            return Ok(new { message = "部署删除成功" });
        }
    }
}

using System;
using System.Threading.Tasks;
using FlowableWrapper.Api.Filters;
using FlowableWrapper.Application.Dtos;
using FlowableWrapper.Application.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace FlowableWrapper.Api.Controllers
{
    /// <summary>
    /// Flowable HTTP Task 回调接收接口
    ///
    /// 此接口仅由 Flowable 引擎调用，不由业务系统或前端直接调用。
    /// URL 配置：appsettings.json → Flowable.FrameworkCallbackUrl
    ///
    /// Flowable HTTP Task 重试行为：
    ///   2xx  → 成功，Flowable 流程正常结束
    ///   5xx  → 失败，Flowable 触发重试（按 BPMN HTTP Task 配置的重试次数）
    ///   超限 → 进 Flowable 死信队列，运维人工处理
    ///
    /// ⚠ 注意：此 Controller 不使用 GlobalExceptionFilter 的 400 转换
    ///         所有异常必须返回 5xx，否则 Flowable 不会触发重试
    /// </summary>
    [ApiController]
    [Route("api/callback")]
    public class CallbackController : ControllerBase
    {
        private readonly ProcessCallbackAppService _callbackService;
        private readonly ILogger<CallbackController> _logger;

        public CallbackController(
            ProcessCallbackAppService callbackService,
            ILogger<CallbackController> logger)
        {
            _callbackService = callbackService;
            _logger          = logger;
        }

        /// <summary>
        /// 接收 Flowable HTTP Task 回调
        /// POST /api/callback/flowable
        ///
        /// BPMN 中 HTTP Task 配置参考：
        ///   requestMethod  : POST
        ///   requestUrl     : ${frameworkCallbackUrl}
        ///   requestHeaders : Content-Type: application/json
        ///   requestBody    : {
        ///                      "processInstanceId":"${execution.processInstanceId}",
        ///                      "businessId":"${businessId}",
        ///                      "processDefinitionKey":"${processDefinitionKey}"
        ///                    }
        /// </summary>
        [AllowAnonymous]
        [HttpPost("flowable")]
        public async Task<ActionResult<FlowableCallbackResponse>> HandleFlowableCallback(
            [FromBody] FlowableCallbackRequest request)
        {
            try
            {
                var result = await _callbackService.HandleFlowableCallbackAsync(request);

                // 返回 200：Flowable 认为回调处理成功，流程正常结束
                return Ok(result);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex,
                    "Flowable 回调处理失败，返回 500 触发 Flowable 重试: " +
                    "ProcessInstanceId={ProcessInstanceId}",
                    request?.ProcessInstanceId);

                // 返回 500：触发 Flowable HTTP Task 重试机制
                // ⚠ 不能返回 400（Flowable 认为客户端错误，不重试）
                return StatusCode(500, new FlowableCallbackResponse
                {
                    Success = false,
                    Message = ex.Message
                });
            }
        }
    }
}

using System.Threading.Tasks;
using FlowableWrapper.Api.Filters;
using FlowableWrapper.Application.Dtos;
using FlowableWrapper.Application.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace FlowableWrapper.Api.Controllers
{
    /// <summary>
    /// 流程生命周期接口
    /// </summary>
    [ApiController]
    [Route("api/processes")]
    public class ProcessController : ControllerBase
    {
        private readonly ProcessLifecycleAppService _lifecycleService;
        private readonly ILogger<ProcessController> _logger;

        public ProcessController(
            ProcessLifecycleAppService lifecycleService,
            ILogger<ProcessController> logger)
        {
            _lifecycleService = lifecycleService;
            _logger           = logger;
        }

        /// <summary>
        /// 启动流程
        /// POST /api/processes/start
        ///
        /// 调用示例：
        /// {
        ///   "businessType": "personnel_selection_approval",
        ///   "businessId": "SELECTION_2024_001",
        ///   "initialSlotSelections": [
        ///     { "slotKey": "group_leader", "users": ["EMP_001"] }
        ///   ],
        ///   "businessVariables": { "title": "2024年第一批选调" },
        ///   "callback": { "url": "https://biz-system/api/workflow/callback" }
        /// }
        /// </summary>
        [HttpPost("start")]
        public async Task<ActionResult<ApiResult<StartProcessResponse>>> StartProcess(
            [FromBody] StartProcessRequest request)
        {
            var result = await _lifecycleService.StartProcessAsync(request);
            return Ok(ApiResult<StartProcessResponse>.Ok(result));
        }

        /// <summary>
        /// 终止流程（管理员操作）
        /// POST /api/processes/terminate
        /// </summary>
        [HttpPost("terminate")]
        public async Task<ActionResult<ApiResult<object>>> TerminateProcess(
            [FromBody] TerminateProcessRequest request)
        {
            await _lifecycleService.TerminateProcessAsync(request);
            return Ok(ApiResult.OkEmpty("流程已终止"));
        }
    }
}

